mkdir -p /app/bin /app/out; cat > /app/bin/boards.py <<'EOF'
import sys, os, csv, json
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read(d, name):
    p = os.path.join(d, name)
    if not os.path.exists(p):
        return []
    with open(p, encoding="utf-8-sig", newline="") as f:
        rows = list(csv.reader(f))
    rows = [r for r in rows if any(c.strip() for c in r)]
    if not rows:
        return []
    hdr = [h.strip() for h in rows[0]]
    out = []
    for r in rows[1:]:
        rec = {}
        for i, h in enumerate(hdr):
            rec[h] = r[i].strip() if i < len(r) else ""
        out.append(rec)
    return out


def ft(s):
    h, m, sec = s.split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def fmt(instant, tz):
    dt = instant.astimezone(tz)
    off = dt.utcoffset()
    secs = int(off.total_seconds())
    sign = "+" if secs >= 0 else "-"
    secs = abs(secs)
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + "%s%02d:%02d" % (sign, secs // 3600, secs % 3600 // 60)


def main(indir, outfile):
    req = json.load(open(os.path.join(indir, "request.json"), encoding="utf-8-sig"))
    dates = sorted(set(req["service_dates"]))
    agencies = read(indir, "agency.txt")
    agtz = {a["agency_id"]: a["agency_timezone"] for a in agencies}
    default_tz = agencies[0]["agency_timezone"]
    stops = {s["stop_id"]: s for s in read(indir, "stops.txt")}
    routes = {r["route_id"]: r for r in read(indir, "routes.txt")}
    trips = {t["trip_id"]: t for t in read(indir, "trips.txt")}
    cal = {c["service_id"]: c for c in read(indir, "calendar.txt")}
    exc = {}
    for e in read(indir, "calendar_dates.txt"):
        exc[(e["service_id"], e["date"])] = e["exception_type"]
    freqs = {}
    for f in read(indir, "frequencies.txt"):
        freqs.setdefault(f["trip_id"], []).append(f)
    st = {}
    for r in read(indir, "stop_times.txt"):
        st.setdefault(r["trip_id"], []).append(r)

    def board_stop(sid):
        s = stops[sid]
        p = s.get("parent_station", "")
        if p and p in stops:
            return p
        return sid

    boardstops = {}
    for sid, s in stops.items():
        lt = s.get("location_type", "")
        if lt == "1" or (lt in ("", "0") and not s.get("parent_station", "")):
            boardstops[sid] = s

    def btz(sid):
        return ZoneInfo(boardstops[sid].get("stop_timezone") or default_tz)

    def runs(sv, d):
        e = exc.get((sv, d.strftime("%Y%m%d")))
        if e == "1":
            return True
        if e == "2":
            return False
        c = cal.get(sv)
        if not c:
            return False
        ds = d.strftime("%Y%m%d")
        if not (c["start_date"] <= ds <= c["end_date"]):
            return False
        return c[["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"][d.weekday()]] == "1"

    # precompute trip stop info
    tinfo = {}
    for tid, rows in st.items():
        if tid not in trips:
            continue
        rows = sorted(rows, key=lambda r: int(r["stop_sequence"]))
        times = []
        for r in rows:
            t = r.get("departure_time") or r.get("arrival_time") or ""
            times.append(ft(t) if t else None)
        n = len(rows)
        i = 0
        while i < n:
            if times[i] is None:
                b = i - 1
                a = i
                while times[a] is None:
                    a += 1
                steps = a - b
                for k in range(i, a):
                    times[k] = times[b] + (times[a] - times[b]) * (k - b) // steps
                i = a
            i += 1
        last = rows[-1]["stop_id"]
        lsid = board_stop(last)
        lastname = stops[lsid]["stop_name"]
        tinfo[tid] = (rows, times, lastname)

    boards = {}
    for sid in boardstops:
        for d in dates:
            boards[(sid, d)] = []

    for dstr in dates:
        d = date.fromisoformat(dstr)
        for tid, t in trips.items():
            if tid not in tinfo or not runs(t["service_id"], d):
                continue
            rt = routes[t["route_id"]]
            ag = rt["agency_id"]
            tz = ZoneInfo(agtz[ag])
            noon = datetime(d.year, d.month, d.day, 12, tzinfo=tz).astimezone(timezone.utc)
            origin = noon - timedelta(hours=12)
            label = rt.get("route_short_name") or rt.get("route_long_name") or ""
            rows, times, lastname = tinfo[tid]
            deps = []
            for idx, r in enumerate(rows):
                if idx == len(rows) - 1 or r.get("pickup_type", "") == "1":
                    continue
                hs = r.get("stop_headsign") or t.get("trip_headsign") or lastname
                deps.append((idx, r, hs))
            entries = []  # (kind, time, until, headway, r, hs)
            if tid in freqs:
                base = times[0]
                for w in freqs[tid]:
                    s0, e0, hw = ft(w["start_time"]), ft(w["end_time"]), int(w["headway_secs"])
                    if s0 >= e0:
                        continue
                    starts = list(range(s0, e0, hw))
                    exact = w.get("exact_times", "") == "1"
                    for idx, r, hs in deps:
                        off = times[idx] - base
                        if exact:
                            for s in starts:
                                entries.append(("scheduled", s + off, None, None, r, hs))
                        else:
                            entries.append(("interval", starts[0] + off, starts[-1] + off, hw, r, hs))
            else:
                for idx, r, hs in deps:
                    entries.append(("scheduled", times[idx], None, None, r, hs))
            for kind, a, u, hw, r, hs in entries:
                sid = board_stop(r["stop_id"])
                if sid not in boardstops:
                    continue
                inst = origin + timedelta(seconds=a)
                uinst = origin + timedelta(seconds=u) if u is not None else None
                bz = btz(sid)
                plat = stops[r["stop_id"]].get("platform_code", "") or None
                key = (inst, label, hs, tid, (0, "") if plat is None else (1, plat))
                boards[(sid, dstr)].append((key, {
                    "kind": kind, "time": fmt(inst, bz),
                    "until": fmt(uinst, bz) if uinst is not None else None,
                    "headway_secs": hw, "route": label, "headsign": hs,
                    "trip": tid, "platform": plat, "agency": ag}))

    out = []
    for (sid, dstr) in sorted(boards):
        b = boardstops[sid]
        deps = [x[1] for x in sorted(boards[(sid, dstr)], key=lambda x: x[0])]
        out.append({"stop_id": sid, "name": b["stop_name"], "timezone": str(btz(sid)),
                    "service_date": dstr, "departures": deps})
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump({"service_dates": dates, "boards": out}, f, ensure_ascii=False)


main(sys.argv[1], sys.argv[2])
